CREATE TABLE public.moot_court_registrations (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, status TEXT NOT NULL DEFAULT 'pending', paddle_transaction_id TEXT, environment TEXT NOT NULL DEFAULT 'sandbox', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT INSERT ON public.moot_court_registrations TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.moot_court_registrations TO authenticated; GRANT ALL ON public.moot_court_registrations TO service_role; ALTER TABLE public.moot_court_registrations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can register" ON public.moot_court_registrations FOR INSERT TO anon, authenticated WITH CHECK (true);